-- ======================================================================================================================
-- Anibros CRM multi-client edition: MySQL / MariaDB schema (utf8mb4, InnoDB)
--
-- Ported from the PostgreSQL schema of the Node.js version (migrations 001-034, final state).
--   * UUID primary keys are CHAR(36) ascii_bin (lower-case, generated by the application).
--   * Timestamps are DATETIME(3) in UTC. The application sets the session time zone to +00:00.
--   * PostgreSQL arrays and jsonb are stored as JSON text in MEDIUMTEXT columns; the application always supplies them.
--   * PostgreSQL "partial unique indexes" are expressed with generated helper columns (NULL = not subject to the rule).
--   * Cross-table references are COMPOSITE foreign keys (child_id, tenant_id) -> parent(id, tenant_id): a row can never point at
--     another tenant's row.
--   * No triggers and no stored routines that need SUPER (cPanel hosts with binary logging refuse them). The logic that lived in
--     PostgreSQL triggers is in the PHP services. Row-level security is provided by views: see app/Core/Views.php.
--
-- Run through bin/migrate.php (or import in phpMyAdmin, then run bin/migrate.php --views to (re)generate the views).
-- ======================================================================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ── identity & tenancy ──────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS users (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  email VARCHAR(254) NOT NULL,
  password_hash VARCHAR(255) CHARACTER SET ascii NOT NULL,
  name VARCHAR(200) NOT NULL,
  avatar_url VARCHAR(2000) NULL,
  phone VARCHAR(40) NULL,
  email_verified TINYINT(1) NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata',
  locale VARCHAR(16) NOT NULL DEFAULT 'en-IN',
  password_changed_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY users_email_key (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS organisations (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(200) NOT NULL,
  slug VARCHAR(80) CHARACTER SET ascii NOT NULL,
  owner_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY organisations_slug_key (slug),
  CONSTRAINT organisations_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tenants (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organisation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(200) NOT NULL,
  slug VARCHAR(80) CHARACTER SET ascii NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  settings MEDIUMTEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata',
  default_currency CHAR(3) CHARACTER SET ascii NOT NULL DEFAULT 'INR',
  kind ENUM('agency_hq','client') NOT NULL DEFAULT 'client',
  industry ENUM('real_estate','healthcare','restaurant','finance','retail','education','beauty_wellness','automotive','travel','professional_services','other') NULL,
  website VARCHAR(300) NULL,
  contact_name VARCHAR(150) NULL,
  contact_email VARCHAR(254) NULL,
  contact_phone VARCHAR(40) NULL,
  notes TEXT NULL,
  archived_at DATETIME(3) NULL,
  hq_flag TINYINT GENERATED ALWAYS AS (IF(kind = 'agency_hq', 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_tenant_org_slug (organisation_id, slug),
  UNIQUE KEY uq_tenants_one_hq (organisation_id, hq_flag),
  KEY idx_tenants_org_kind (organisation_id, kind, archived_at),
  CONSTRAINT tenants_organisation_id_fkey FOREIGN KEY (organisation_id) REFERENCES organisations (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tenant_memberships (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  role ENUM('tenant_owner','tenant_admin','sales_manager','sales_agent','marketing_manager','marketing_analyst','executive_readonly','auditor') NOT NULL DEFAULT 'sales_agent',
  status ENUM('active','suspended','invited','revoked') NOT NULL DEFAULT 'active',
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  invited_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  updated_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  work_channels MEDIUMTEXT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_tenant_user_membership (tenant_id, user_id),
  KEY idx_memberships_user (user_id),
  KEY idx_memberships_tenant_role (tenant_id, role, status),
  CONSTRAINT tenant_memberships_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT tenant_memberships_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT tenant_memberships_invited_by_fkey FOREIGN KEY (invited_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT tenant_memberships_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tenant_invitations (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  email VARCHAR(254) NOT NULL,
  role ENUM('tenant_owner','tenant_admin','sales_manager','sales_agent','marketing_manager','marketing_analyst','executive_readonly','auditor') NOT NULL,
  invited_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  accepted_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  revoked_at DATETIME(3) NULL,
  accepted_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  pending TINYINT GENERATED ALWAYS AS (IF(accepted_at IS NULL AND revoked_at IS NULL, 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY tenant_invitations_token_hash_key (token_hash),
  UNIQUE KEY uq_invitation_pending (tenant_id, email, pending),
  CONSTRAINT tenant_invitations_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT tenant_invitations_invited_by_fkey FOREIGN KEY (invited_by) REFERENCES users (id) ON DELETE RESTRICT,
  CONSTRAINT tenant_invitations_accepted_by_fkey FOREIGN KEY (accepted_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sessions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  ip_address VARCHAR(64) NULL,
  user_agent VARCHAR(400) NULL,
  expires_at DATETIME(3) NOT NULL,
  revoked_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  last_seen_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  device_label VARCHAR(120) NULL,
  active_tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  auth_level TINYINT NOT NULL DEFAULT 1,
  mfa_verified_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY sessions_token_hash_key (token_hash),
  KEY idx_sessions_user (user_id, expires_at),
  KEY idx_sessions_active_tenant (active_tenant_id),
  CONSTRAINT sessions_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT sessions_active_tenant_id_fkey FOREIGN KEY (active_tenant_id) REFERENCES tenants (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS login_attempts (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  email VARCHAR(254) NOT NULL,
  ip_address VARCHAR(64) NULL,
  success TINYINT(1) NOT NULL DEFAULT 0,
  attempted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_login_attempts_email_time (email, attempted_at),
  KEY idx_login_attempts_ip_time (ip_address, attempted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS email_verification_tokens (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  used_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY email_verification_tokens_token_hash_key (token_hash),
  KEY idx_email_verification_user (user_id),
  CONSTRAINT email_verification_tokens_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  used_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY password_reset_tokens_token_hash_key (token_hash),
  KEY idx_password_reset_user (user_id),
  CONSTRAINT password_reset_tokens_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS mfa_factors (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  type ENUM('totp') NOT NULL DEFAULT 'totp',
  secret_enc TEXT CHARACTER SET ascii NOT NULL,
  confirmed_at DATETIME(3) NULL,
  last_used_step BIGINT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  confirmed_flag TINYINT GENERATED ALWAYS AS (IF(confirmed_at IS NOT NULL, 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_mfa_one_confirmed_per_user (user_id, confirmed_flag),
  CONSTRAINT mfa_factors_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS mfa_recovery_codes (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  code_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  used_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_mfa_recovery_user (user_id, used_at),
  CONSTRAINT mfa_recovery_codes_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS branches (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(200) NOT NULL,
  code VARCHAR(40) NOT NULL,
  address VARCHAR(500) NULL,
  city VARCHAR(120) NULL,
  state VARCHAR(120) NULL,
  country VARCHAR(8) NOT NULL DEFAULT 'IN',
  phone VARCHAR(40) NULL,
  email VARCHAR(254) NULL,
  manager_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_branch_tenant_code (tenant_id, code),
  UNIQUE KEY uq_branch_tenant_composite (id, tenant_id),
  CONSTRAINT branches_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT branches_manager_id_fkey FOREIGN KEY (manager_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── contacts ────────────────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS contacts (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  first_name VARCHAR(150) NOT NULL,
  last_name VARCHAR(150) NULL,
  email VARCHAR(254) NULL,
  phone VARCHAR(40) NULL,
  source_summary MEDIUMTEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at DATETIME(3) NULL,
  company VARCHAR(200) NULL,
  job_title VARCHAR(150) NULL,
  city VARCHAR(120) NULL,
  owner_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  tags MEDIUMTEXT NOT NULL,
  custom_fields MEDIUMTEXT NOT NULL,
  version INT NOT NULL DEFAULT 1,
  merged_into_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  display_name VARCHAR(310) GENERATED ALWAYS AS (TRIM(CONCAT(first_name, ' ', COALESCE(last_name, '')))) STORED,
  PRIMARY KEY (id),
  UNIQUE KEY uq_contact_tenant_composite (id, tenant_id),
  KEY idx_contacts_active (tenant_id, deleted_at, created_at),
  KEY idx_contacts_email (tenant_id, email),
  KEY idx_contacts_phone (tenant_id, phone),
  KEY idx_contacts_name_live (tenant_id, display_name, id),
  KEY idx_contacts_owner_live (tenant_id, owner_id),
  KEY idx_contacts_updated_live (tenant_id, updated_at, id),
  CONSTRAINT contacts_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT contacts_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT contacts_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS contact_identifiers (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  contact_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind ENUM('email','phone') NOT NULL,
  value VARCHAR(254) NOT NULL,
  is_primary TINYINT(1) NOT NULL DEFAULT 0,
  released_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  live_flag TINYINT GENERATED ALWAYS AS (IF(released_at IS NULL, 1, NULL)) VIRTUAL,
  primary_flag TINYINT GENERATED ALWAYS AS (IF(is_primary = 1 AND released_at IS NULL, 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_identifier_live (tenant_id, kind, value, live_flag),
  UNIQUE KEY uq_identifier_primary (contact_id, kind, primary_flag),
  KEY idx_identifiers_contact (contact_id),
  CONSTRAINT contact_identifiers_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_identifier_contact_tenant FOREIGN KEY (contact_id, tenant_id) REFERENCES contacts (id, tenant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS contact_merges (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  survivor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  merged_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  snapshot MEDIUMTEXT NOT NULL,
  merged_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  undone_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY idx_contact_merges_survivor (tenant_id, survivor_id, created_at),
  CONSTRAINT contact_merges_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_merge_survivor FOREIGN KEY (survivor_id, tenant_id) REFERENCES contacts (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT fk_merge_merged FOREIGN KEY (merged_id, tenant_id) REFERENCES contacts (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT contact_merges_merged_by_fkey FOREIGN KEY (merged_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT ck_merge_distinct CHECK (survivor_id <> merged_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS communication_consents (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  contact_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  channel ENUM('email','sms','whatsapp','push','phone_call') NOT NULL,
  status ENUM('granted','revoked','expired') NOT NULL DEFAULT 'granted',
  source VARCHAR(100) NOT NULL DEFAULT 'manual',
  legal_basis VARCHAR(100) NOT NULL DEFAULT 'consent',
  ip_address VARCHAR(64) NULL,
  user_agent VARCHAR(400) NULL,
  proof_url VARCHAR(2000) NULL,
  double_opt_in_confirmed_at DATETIME(3) NULL,
  expires_at DATETIME(3) NULL,
  revoked_at DATETIME(3) NULL,
  revoke_reason VARCHAR(500) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_consents_contact_channel (tenant_id, contact_id, channel, created_at),
  KEY idx_consents_channel (tenant_id, channel, status),
  CONSTRAINT communication_consents_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_consent_contact_tenant FOREIGN KEY (contact_id, tenant_id) REFERENCES contacts (id, tenant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── pipelines & leads ───────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS pipelines (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(200) NOT NULL,
  is_default TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  description TEXT NULL,
  archived_at DATETIME(3) NULL,
  reason_codes_required TINYINT(1) NOT NULL DEFAULT 0,
  template VARCHAR(60) NULL,
  deal_value_required TINYINT(1) NOT NULL DEFAULT 0,
  default_flag TINYINT GENERATED ALWAYS AS (IF(is_default = 1 AND archived_at IS NULL, 1, NULL)) VIRTUAL,
  template_live VARCHAR(60) GENERATED ALWAYS AS (IF(template IS NOT NULL AND archived_at IS NULL, template, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pipeline_tenant_composite (id, tenant_id),
  UNIQUE KEY uq_default_pipeline_per_tenant (tenant_id, default_flag),
  UNIQUE KEY uq_pipeline_template (tenant_id, template_live),
  CONSTRAINT pipelines_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pipeline_stages (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  pipeline_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(200) NOT NULL,
  order_index INT NOT NULL DEFAULT 0,
  color VARCHAR(20) NOT NULL DEFAULT '#3B82F6',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  stage_key VARCHAR(60) NULL,
  maps_to_status ENUM('open','contacted','qualified','viewing_scheduled','negotiation','won','lost','disqualified') NOT NULL DEFAULT 'open',
  probability SMALLINT NOT NULL DEFAULT 0,
  archived_at DATETIME(3) NULL,
  key_live VARCHAR(60) GENERATED ALWAYS AS (IF(stage_key IS NOT NULL AND archived_at IS NULL, stage_key, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pipeline_stage_tenant_composite (id, tenant_id),
  UNIQUE KEY uq_stage_key_per_pipeline (pipeline_id, key_live),
  KEY idx_stages_pipeline_order (pipeline_id, order_index),
  CONSTRAINT fk_stage_pipeline_tenant FOREIGN KEY (pipeline_id, tenant_id) REFERENCES pipelines (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT ck_stage_probability CHECK (probability >= 0 AND probability <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pipeline_stage_transitions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  pipeline_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  from_stage_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  to_stage_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  from_stage_key VARCHAR(60) NOT NULL,
  to_stage_key VARCHAR(60) NOT NULL,
  is_allowed TINYINT(1) NOT NULL DEFAULT 1,
  required_fields MEDIUMTEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_stage_transition (pipeline_id, from_stage_key, to_stage_key),
  KEY idx_transitions_tenant (tenant_id),
  CONSTRAINT pipeline_stage_transitions_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_transition_pipeline_tenant FOREIGN KEY (pipeline_id, tenant_id) REFERENCES pipelines (id, tenant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS leads (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  contact_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  pipeline_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  stage_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  source ENUM('website','referral','portal','direct','meta_ads','google_ads','walk_in','other') NOT NULL DEFAULT 'other',
  status ENUM('open','contacted','qualified','viewing_scheduled','negotiation','won','lost','disqualified') NOT NULL DEFAULT 'open',
  lead_score INT NOT NULL DEFAULT 0,
  estimated_value DECIMAL(14,2) NULL DEFAULT 0,
  currency CHAR(3) CHARACTER SET ascii NOT NULL DEFAULT 'INR',
  custom_fields MEDIUMTEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  stage_key VARCHAR(60) NULL,
  deleted_at DATETIME(3) NULL,
  branch_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  tags MEDIUMTEXT NOT NULL,
  version INT NOT NULL DEFAULT 1,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  assigned_at DATETIME(3) NULL,
  closed_at DATETIME(3) NULL,
  loss_reason VARCHAR(500) NULL,
  budget_min DECIMAL(14,2) NULL,
  budget_max DECIMAL(14,2) NULL,
  bedrooms_min SMALLINT NULL,
  locations MEDIUMTEXT NOT NULL,
  property_types MEDIUMTEXT NOT NULL,
  listing_type ENUM('sale','rent','lease') NULL,
  campaign VARCHAR(200) NULL,
  first_response_due_at DATETIME(3) NULL,
  first_response_at DATETIME(3) NULL,
  last_activity_at DATETIME(3) NULL,
  next_followup_at DATETIME(3) NULL,
  score_breakdown MEDIUMTEXT NOT NULL,
  source_details MEDIUMTEXT NOT NULL,
  loss_reason_code VARCHAR(60) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_lead_tenant_composite (id, tenant_id),
  KEY idx_leads_active (tenant_id, deleted_at, created_at, id),
  KEY idx_leads_owner_created (tenant_id, owner_id, created_at, id),
  KEY idx_leads_stage_created (tenant_id, stage_id, created_at, id),
  KEY idx_leads_tenant_status (tenant_id, status),
  KEY idx_leads_tenant_source (tenant_id, source),
  KEY idx_leads_tenant_contact (tenant_id, contact_id),
  KEY idx_leads_score (tenant_id, lead_score, id),
  KEY idx_leads_followup (tenant_id, next_followup_at),
  KEY idx_leads_sla_open (tenant_id, first_response_due_at),
  KEY idx_leads_updated (tenant_id, updated_at, id),
  KEY idx_leads_branch (branch_id),
  CONSTRAINT leads_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_contact_tenant FOREIGN KEY (contact_id, tenant_id) REFERENCES contacts (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT fk_lead_pipeline_tenant FOREIGN KEY (pipeline_id, tenant_id) REFERENCES pipelines (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT fk_lead_stage_tenant FOREIGN KEY (stage_id, tenant_id) REFERENCES pipeline_stages (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT leads_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT leads_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT leads_branch_id_fkey FOREIGN KEY (branch_id) REFERENCES branches (id) ON DELETE SET NULL,
  CONSTRAINT ck_leads_score CHECK (lead_score >= 0 AND lead_score <= 100),
  CONSTRAINT ck_leads_value CHECK (estimated_value IS NULL OR estimated_value >= 0),
  CONSTRAINT ck_leads_budget CHECK (budget_min IS NULL OR budget_max IS NULL OR budget_min <= budget_max)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lead_handlers (
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  added_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (lead_id, user_id),
  KEY idx_lead_handlers_user (tenant_id, user_id),
  CONSTRAINT lead_handlers_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_handler_lead FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT lead_handlers_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT lead_handlers_added_by_fkey FOREIGN KEY (added_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lead_stage_history (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  from_stage_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  to_stage_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  changed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  reason VARCHAR(1000) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  from_stage_name VARCHAR(200) NULL,
  to_stage_name VARCHAR(200) NULL,
  to_status ENUM('open','contacted','qualified','viewing_scheduled','negotiation','won','lost','disqualified') NULL,
  to_probability SMALLINT NULL,
  reason_code VARCHAR(60) NULL,
  snapshot_backfilled TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_lead_stage_history_lead (lead_id, created_at),
  CONSTRAINT fk_stage_history_lead_tenant FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT fk_stage_history_to_stage_tenant FOREIGN KEY (to_stage_id, tenant_id) REFERENCES pipeline_stages (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT lead_stage_history_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS activities (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  type ENUM('note','call','email','meeting','viewing','status_change','stage_change','task_created','task_completed','whatsapp','sms','instagram') NOT NULL DEFAULT 'note',
  description TEXT NOT NULL,
  metadata MEDIUMTEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  direction ENUM('outbound','inbound') NULL,
  outcome VARCHAR(100) NULL,
  duration_minutes INT NULL,
  PRIMARY KEY (id),
  KEY idx_activities_tenant_lead (tenant_id, lead_id, created_at),
  KEY idx_activities_tenant (tenant_id, created_at),
  KEY idx_activities_tenant_user (tenant_id, user_id, created_at),
  CONSTRAINT activities_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_activity_lead_tenant FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT activities_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT ck_activities_duration CHECK (duration_minutes IS NULL OR (duration_minutes >= 0 AND duration_minutes <= 1440))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS saved_views (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  entity ENUM('lead','contact') NOT NULL,
  name VARCHAR(80) NOT NULL,
  filters MEDIUMTEXT NOT NULL,
  sort VARCHAR(100) NULL,
  is_shared TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_saved_view_name (tenant_id, owner_id, entity, name),
  KEY idx_saved_views_lookup (tenant_id, entity, is_shared, owner_id),
  CONSTRAINT saved_views_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT saved_views_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lead_scoring_config (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  weight_source_meta_ads INT NOT NULL DEFAULT 20,
  weight_source_google_ads INT NOT NULL DEFAULT 20,
  weight_source_referral INT NOT NULL DEFAULT 30,
  weight_source_website INT NOT NULL DEFAULT 15,
  weight_source_portal INT NOT NULL DEFAULT 10,
  weight_source_walk_in INT NOT NULL DEFAULT 25,
  weight_source_other INT NOT NULL DEFAULT 5,
  weight_viewing_scheduled INT NOT NULL DEFAULT 15,
  weight_viewing_completed INT NOT NULL DEFAULT 25,
  weight_call_made INT NOT NULL DEFAULT 10,
  weight_email_replied INT NOT NULL DEFAULT 10,
  recency_decay_days INT NOT NULL DEFAULT 30,
  weight_budget_fit_exact INT NOT NULL DEFAULT 20,
  weight_budget_fit_close INT NOT NULL DEFAULT 10,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_scoring_config_tenant (tenant_id),
  CONSTRAINT lead_scoring_config_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS import_jobs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind ENUM('leads') NOT NULL,
  status ENUM('queued','running','completed','failed') NOT NULL DEFAULT 'queued',
  file_name VARCHAR(255) NULL,
  file_sha256 CHAR(64) CHARACTER SET ascii NOT NULL,
  payload_csv MEDIUMTEXT NULL,
  mapping MEDIUMTEXT NOT NULL,
  options MEDIUMTEXT NOT NULL,
  total_rows INT NOT NULL DEFAULT 0,
  processed_rows INT NOT NULL DEFAULT 0,
  created_count INT NOT NULL DEFAULT 0,
  matched_count INT NOT NULL DEFAULT 0,
  skipped_count INT NOT NULL DEFAULT 0,
  error_count INT NOT NULL DEFAULT 0,
  errors MEDIUMTEXT NOT NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  started_at DATETIME(3) NULL,
  finished_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  active_flag TINYINT GENERATED ALWAYS AS (IF(status IN ('queued','running'), 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_import_active_file (tenant_id, kind, file_sha256, active_flag),
  KEY idx_import_jobs_tenant (tenant_id, created_at),
  CONSTRAINT import_jobs_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT import_jobs_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── custom fields ───────────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS custom_field_definitions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  entity_type ENUM('lead','contact','property','viewing') NOT NULL,
  name VARCHAR(200) NOT NULL,
  label VARCHAR(60) NOT NULL,
  field_key VARCHAR(40) CHARACTER SET ascii NOT NULL,
  field_type ENUM('text','number','date','boolean','select','multi_select','url','email') NOT NULL DEFAULT 'text',
  is_required TINYINT(1) NOT NULL DEFAULT 0,
  is_visible TINYINT(1) NOT NULL DEFAULT 1,
  options MEDIUMTEXT NOT NULL,
  default_value VARCHAR(500) NULL,
  validation_regex VARCHAR(500) NULL,
  order_index INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  help_text VARCHAR(200) NULL,
  show_in_list TINYINT(1) NOT NULL DEFAULT 0,
  label_norm VARCHAR(60) GENERATED ALWAYS AS (TRIM(label)) VIRTUAL,
  visible_flag TINYINT GENERATED ALWAYS AS (IF(is_visible = 1, 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_custom_field_def_tenant (id, tenant_id),
  UNIQUE KEY uq_custom_field_key (tenant_id, entity_type, field_key),
  UNIQUE KEY uq_cfd_visible_label (tenant_id, entity_type, label_norm, visible_flag),
  CONSTRAINT custom_field_definitions_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS custom_field_values (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  field_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  entity_type ENUM('lead','contact','property','viewing') NOT NULL,
  entity_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  value TEXT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_custom_field_value (field_id, entity_id),
  KEY idx_custom_field_values_entity (tenant_id, entity_type, entity_id),
  CONSTRAINT custom_field_values_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_custom_field_value_def_tenant FOREIGN KEY (field_id, tenant_id) REFERENCES custom_field_definitions (id, tenant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── inventory ───────────────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS projects (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(150) NOT NULL,
  description TEXT NULL,
  location VARCHAR(300) NULL,
  status ENUM('upcoming','active','on_hold','completed') NOT NULL DEFAULT 'active',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  developer VARCHAR(200) NULL,
  city VARCHAR(120) NULL,
  locality VARCHAR(160) NULL,
  address VARCHAR(500) NULL,
  rera_id VARCHAR(80) NULL,
  possession_date DATE NULL,
  amenities MEDIUMTEXT NOT NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  version INT NOT NULL DEFAULT 1,
  deleted_at DATETIME(3) NULL,
  name_norm VARCHAR(150) GENERATED ALWAYS AS (TRIM(name)) VIRTUAL,
  live_flag TINYINT GENERATED ALWAYS AS (IF(deleted_at IS NULL, 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_project_tenant_composite (id, tenant_id),
  UNIQUE KEY uq_project_name_live (tenant_id, name_norm, live_flag),
  KEY idx_projects_list (tenant_id, name, id),
  CONSTRAINT projects_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT projects_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS properties (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  title VARCHAR(200) NOT NULL,
  description TEXT NULL,
  property_type ENUM('apartment','villa','townhouse','penthouse','office','retail','plot','other') NOT NULL DEFAULT 'apartment',
  listing_type ENUM('sale','rent','lease') NOT NULL DEFAULT 'sale',
  status ENUM('available','under_offer','reserved','sold','rented','inactive') NOT NULL DEFAULT 'available',
  price DECIMAL(14,2) NOT NULL DEFAULT 0,
  currency CHAR(3) CHARACTER SET ascii NOT NULL DEFAULT 'INR',
  bedrooms INT NULL DEFAULT 0,
  bathrooms INT NULL DEFAULT 0,
  area_sqft DECIMAL(10,2) NULL DEFAULT 0,
  location VARCHAR(300) NULL,
  metadata MEDIUMTEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  branch_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  unit_number VARCHAR(60) NULL,
  tower VARCHAR(60) NULL,
  floor INT NULL,
  facing VARCHAR(40) NULL,
  furnishing ENUM('unfurnished','semi_furnished','furnished') NULL,
  carpet_area_sqft DECIMAL(10,2) NULL,
  address VARCHAR(500) NULL,
  city VARCHAR(120) NULL,
  locality VARCHAR(160) NULL,
  possession_date DATE NULL,
  rera_id VARCHAR(80) NULL,
  amenities MEDIUMTEXT NOT NULL,
  tags MEDIUMTEXT NOT NULL,
  owner_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  negotiable TINYINT(1) NOT NULL DEFAULT 1,
  status_changed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  cover_file_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  version INT NOT NULL DEFAULT 1,
  deleted_at DATETIME(3) NULL,
  price_per_sqft DECIMAL(12,2) GENERATED ALWAYS AS (IF(area_sqft > 0, ROUND(price / area_sqft, 2), NULL)) STORED,
  tower_norm VARCHAR(60) GENERATED ALWAYS AS (COALESCE(tower, '')) VIRTUAL,
  unit_live TINYINT GENERATED ALWAYS AS (IF(project_id IS NOT NULL AND unit_number IS NOT NULL AND deleted_at IS NULL, 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_property_tenant_composite (id, tenant_id),
  UNIQUE KEY uq_property_unit_live (tenant_id, project_id, tower_norm, unit_number, unit_live),
  KEY idx_properties_list_new (tenant_id, deleted_at, created_at, id),
  KEY idx_properties_list_price (tenant_id, price, id),
  KEY idx_properties_match (tenant_id, status, listing_type, property_type, price),
  KEY idx_properties_project (tenant_id, project_id, id),
  KEY idx_properties_branch (branch_id),
  CONSTRAINT properties_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_property_project_tenant FOREIGN KEY (project_id, tenant_id) REFERENCES projects (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT properties_branch_id_fkey FOREIGN KEY (branch_id) REFERENCES branches (id) ON DELETE SET NULL,
  CONSTRAINT properties_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT properties_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT ck_property_numbers CHECK (price >= 0 AND COALESCE(bedrooms, 0) >= 0 AND COALESCE(bedrooms, 0) <= 50 AND COALESCE(bathrooms, 0) >= 0 AND COALESCE(bathrooms, 0) <= 50 AND COALESCE(area_sqft, 0) >= 0 AND COALESCE(carpet_area_sqft, 0) >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS property_price_history (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  property_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  price DECIMAL(14,2) NOT NULL,
  currency CHAR(3) CHARACTER SET ascii NOT NULL,
  changed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_pph_property (property_id, created_at, id),
  CONSTRAINT property_price_history_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_pph_property FOREIGN KEY (property_id, tenant_id) REFERENCES properties (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT property_price_history_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS property_status_history (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  property_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  from_status ENUM('available','under_offer','reserved','sold','rented','inactive') NULL,
  to_status ENUM('available','under_offer','reserved','sold','rented','inactive') NOT NULL,
  reason VARCHAR(500) NULL,
  changed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_psh_property (property_id, created_at, id),
  CONSTRAINT property_status_history_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_psh_property FOREIGN KEY (property_id, tenant_id) REFERENCES properties (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT property_status_history_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS files (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  entity_type ENUM('property','project') NOT NULL,
  entity_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind ENUM('image','document') NOT NULL,
  name VARCHAR(200) NOT NULL,
  mime ENUM('image/jpeg','image/png','image/webp','application/pdf') NOT NULL,
  size_bytes INT NOT NULL,
  sha256 CHAR(64) CHARACTER SET ascii NOT NULL,
  storage_key VARCHAR(200) CHARACTER SET ascii NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  deleted_at DATETIME(3) NULL,
  live_flag TINYINT GENERATED ALWAYS AS (IF(deleted_at IS NULL, 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY files_storage_key_key (storage_key),
  UNIQUE KEY uq_files_entity_content (tenant_id, entity_type, entity_id, sha256, live_flag),
  KEY idx_files_entity (tenant_id, entity_type, entity_id, sort_order, created_at),
  CONSTRAINT files_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT files_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT files_size_bytes_check CHECK (size_bytes >= 1 AND size_bytes <= 10485760)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lead_properties (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  property_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  status ENUM('shortlisted','interested','rejected') NOT NULL DEFAULT 'shortlisted',
  source ENUM('manual','matching','viewing','offer') NOT NULL DEFAULT 'manual',
  match_score INT NULL,
  note VARCHAR(500) NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_lead_property (tenant_id, lead_id, property_id),
  KEY idx_lead_properties_lead (tenant_id, lead_id, created_at),
  KEY idx_lead_properties_property (tenant_id, property_id),
  CONSTRAINT lead_properties_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_property_lead FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT fk_lead_property_property FOREIGN KEY (property_id, tenant_id) REFERENCES properties (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT lead_properties_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT ck_lead_property_score CHECK (match_score IS NULL OR (match_score >= 0 AND match_score <= 100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── tasks, viewings, reservations ───────────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS tasks (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  assigned_to CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  title VARCHAR(200) NOT NULL,
  description TEXT NULL,
  priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',
  status ENUM('pending','in_progress','completed','cancelled') NOT NULL DEFAULT 'pending',
  due_date DATETIME(3) NULL,
  completed_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  kind ENUM('todo','call','email','meeting','follow_up') NOT NULL DEFAULT 'todo',
  contact_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  completed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  remind_before_minutes INT NULL,
  remind_at DATETIME(3) NULL,
  reminder_sent_at DATETIME(3) NULL,
  overdue_notified_at DATETIME(3) NULL,
  recurrence MEDIUMTEXT NULL,
  recurrence_root_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  version INT NOT NULL DEFAULT 1,
  deleted_at DATETIME(3) NULL,
  dedupe_key VARCHAR(200) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_task_tenant_composite (id, tenant_id),
  UNIQUE KEY uq_tasks_dedupe (tenant_id, dedupe_key),
  KEY idx_tasks_assignee_open (tenant_id, assigned_to, due_date, id),
  KEY idx_tasks_lead_open (tenant_id, lead_id),
  KEY idx_tasks_contact (tenant_id, contact_id),
  KEY idx_tasks_created (tenant_id, created_at, id),
  KEY idx_tasks_tenant_status (tenant_id, status),
  KEY idx_tasks_reminder_due (remind_at),
  KEY idx_tasks_overdue_due (due_date),
  CONSTRAINT tasks_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_task_lead_tenant FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT fk_task_contact_tenant FOREIGN KEY (contact_id, tenant_id) REFERENCES contacts (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT tasks_assigned_to_fkey FOREIGN KEY (assigned_to) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT tasks_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT tasks_completed_by_fkey FOREIGN KEY (completed_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT ck_tasks_remind CHECK (remind_before_minutes IS NULL OR (remind_before_minutes >= 0 AND remind_before_minutes <= 43200))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS viewings (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  property_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  agent_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  scheduled_at DATETIME(3) NOT NULL,
  duration_minutes INT NOT NULL DEFAULT 30,
  status ENUM('scheduled','confirmed','completed','cancelled','no_show') NOT NULL DEFAULT 'scheduled',
  notes TEXT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version INT NOT NULL DEFAULT 1,
  outcome_code VARCHAR(60) NULL,
  outcome_note VARCHAR(1000) NULL,
  closed_at DATETIME(3) NULL,
  cancel_reason VARCHAR(500) NULL,
  reminder_task_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  slot_flag TINYINT GENERATED ALWAYS AS (IF(status IN ('scheduled','confirmed'), 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_viewing_tenant_composite (id, tenant_id),
  UNIQUE KEY uq_viewings_prevent_double_booking (property_id, scheduled_at, slot_flag),
  KEY idx_viewings_agent_time (agent_id, scheduled_at),
  KEY idx_viewings_lead (lead_id),
  KEY idx_viewings_tenant_scheduled (tenant_id, scheduled_at),
  KEY idx_viewings_tenant_status (tenant_id, status, scheduled_at),
  KEY idx_viewings_reminder_task (reminder_task_id),
  CONSTRAINT viewings_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_viewing_lead_tenant FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT fk_viewing_property_tenant FOREIGN KEY (property_id, tenant_id) REFERENCES properties (id, tenant_id) ON DELETE CASCADE,
  CONSTRAINT viewings_agent_id_fkey FOREIGN KEY (agent_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS reservations (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  property_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  status ENUM('offered','reserved','completed','closed') NOT NULL DEFAULT 'offered',
  offer_price DECIMAL(14,2) NULL,
  agreed_price DECIMAL(14,2) NULL,
  token_amount DECIMAL(14,2) NULL,
  deal_value DECIMAL(14,2) NULL,
  currency CHAR(3) CHARACTER SET ascii NOT NULL,
  hold_until DATETIME(3) NULL,
  note VARCHAR(1000) NULL,
  closed_reason VARCHAR(60) NULL,
  closed_note VARCHAR(500) NULL,
  offered_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  reserved_at DATETIME(3) NULL,
  completed_at DATETIME(3) NULL,
  closed_at DATETIME(3) NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  reserved_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  completed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  closed_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  version INT NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  holder_flag TINYINT GENERATED ALWAYS AS (IF(status = 'reserved', 1, NULL)) VIRTUAL,
  open_flag TINYINT GENERATED ALWAYS AS (IF(status IN ('offered','reserved'), 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reservation_tenant_composite (id, tenant_id),
  UNIQUE KEY uq_reservation_one_holder (tenant_id, property_id, holder_flag),
  UNIQUE KEY uq_reservation_one_open_each (tenant_id, lead_id, property_id, open_flag),
  KEY idx_reservations_lead (tenant_id, lead_id, created_at),
  KEY idx_reservations_property (tenant_id, property_id, status),
  KEY idx_reservations_status (tenant_id, status, created_at, id),
  CONSTRAINT reservations_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_reservation_lead FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT fk_reservation_property FOREIGN KEY (property_id, tenant_id) REFERENCES properties (id, tenant_id) ON DELETE RESTRICT,
  CONSTRAINT reservations_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT reservations_reserved_by_fkey FOREIGN KEY (reserved_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT reservations_completed_by_fkey FOREIGN KEY (completed_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT reservations_closed_by_fkey FOREIGN KEY (closed_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT ck_reservation_closed CHECK ((status = 'closed') = (closed_at IS NOT NULL) AND (status <> 'closed' OR closed_reason IS NOT NULL)),
  CONSTRAINT ck_reservation_completed CHECK (status <> 'completed' OR (completed_at IS NOT NULL AND deal_value IS NOT NULL AND deal_value > 0)),
  CONSTRAINT ck_reservation_reserved CHECK (status <> 'reserved' OR (reserved_at IS NOT NULL AND agreed_price IS NOT NULL AND token_amount IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── notifications ───────────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS notifications (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  role_target ENUM('tenant_owner','tenant_admin','sales_manager','sales_agent','marketing_manager','marketing_analyst','executive_readonly','auditor') NULL,
  title VARCHAR(200) NOT NULL,
  message VARCHAR(500) NOT NULL,
  type VARCHAR(60) NOT NULL DEFAULT 'info',
  metadata MEDIUMTEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  is_read TINYINT(1) NOT NULL DEFAULT 0,
  read_at DATETIME(3) NULL,
  entity_type VARCHAR(60) NULL,
  entity_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  link VARCHAR(500) NULL,
  dedupe_key VARCHAR(200) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_notifications_dedupe (tenant_id, user_id, dedupe_key),
  KEY idx_notifications_inbox (tenant_id, user_id, created_at, id),
  KEY idx_notifications_role (tenant_id, role_target),
  CONSTRAINT notifications_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT notifications_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notification_reads (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  notification_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  read_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_notification_user_read (notification_id, user_id),
  KEY idx_notification_reads_user (user_id),
  CONSTRAINT notification_reads_notification_id_fkey FOREIGN KEY (notification_id) REFERENCES notifications (id) ON DELETE CASCADE,
  CONSTRAINT notification_reads_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── marketing: attribution, spend, channels ─────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS marketing_attribution (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  touch_type ENUM('first_touch','later_touch') NOT NULL DEFAULT 'first_touch',
  campaign VARCHAR(200) NULL,
  source VARCHAR(60) NULL,
  medium VARCHAR(100) NULL,
  ad_group VARCHAR(200) NULL,
  keyword VARCHAR(200) NULL,
  click_id VARCHAR(300) NULL,
  utm_content VARCHAR(200) NULL,
  is_direct TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  backfilled TINYINT(1) NOT NULL DEFAULT 0,
  first_flag TINYINT GENERATED ALWAYS AS (IF(touch_type = 'first_touch', 1, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_attribution_first_touch (tenant_id, lead_id, first_flag),
  KEY idx_attribution_campaign (tenant_id, campaign),
  KEY idx_attribution_lead_time (tenant_id, lead_id, occurred_at, id),
  CONSTRAINT marketing_attribution_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_attribution_lead_tenant FOREIGN KEY (lead_id, tenant_id) REFERENCES leads (id, tenant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS marketing_spend (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  source ENUM('website','referral','portal','direct','meta_ads','google_ads','walk_in','other') NOT NULL,
  campaign VARCHAR(150) NULL,
  period_start DATE NOT NULL,
  period_end DATE NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  currency CHAR(3) CHARACTER SET ascii NOT NULL,
  note VARCHAR(300) NULL,
  import_batch CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  entered_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  version INT NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_marketing_spend_period (tenant_id, period_start, period_end),
  CONSTRAINT marketing_spend_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT marketing_spend_entered_by_fkey FOREIGN KEY (entered_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT ck_spend_amount CHECK (amount >= 0 AND amount < 1000000000000),
  CONSTRAINT ck_spend_period CHECK (period_end >= period_start AND DATEDIFF(period_end, period_start) <= 366)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS channel_mappings (
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  source ENUM('website','referral','portal','direct','meta_ads','google_ads','walk_in','other') NOT NULL,
  channel ENUM('paid_social','paid_search','website','referral','portal','offline','direct','untracked') NOT NULL,
  updated_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (tenant_id, source),
  CONSTRAINT channel_mappings_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT channel_mappings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── automation, integrations, webhooks ──────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS automation_rules (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(200) NOT NULL,
  description TEXT NULL,
  trigger_type ENUM('lead_created','lead_stage_changed','lead_status_changed','viewing_scheduled','viewing_completed','viewing_no_show','task_overdue','task_completed','contact_created','time_based') NOT NULL,
  trigger_config MEDIUMTEXT NOT NULL,
  conditions MEDIUMTEXT NOT NULL,
  actions MEDIUMTEXT NOT NULL,
  status ENUM('active','paused','draft','archived') NOT NULL DEFAULT 'draft',
  run_count INT NOT NULL DEFAULT 0,
  last_run_at DATETIME(3) NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  template VARCHAR(80) NULL,
  params MEDIUMTEXT NOT NULL,
  version INT NOT NULL DEFAULT 1,
  updated_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  active_since DATETIME(3) NULL,
  template_live VARCHAR(80) GENERATED ALWAYS AS (IF(template IS NOT NULL AND status <> 'archived', template, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_automation_rule_template (tenant_id, template_live),
  UNIQUE KEY uq_automation_rule_tenant_composite (id, tenant_id),
  KEY idx_automation_rules_tenant (tenant_id, status),
  KEY idx_automation_rules_trigger (tenant_id, trigger_type, status),
  CONSTRAINT automation_rules_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT automation_rules_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT automation_rules_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS automation_executions (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  rule_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  trigger_entity_type VARCHAR(60) NOT NULL,
  trigger_entity_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  status ENUM('pending','running','completed','failed','skipped') NOT NULL DEFAULT 'pending',
  actions_run INT NOT NULL DEFAULT 0,
  error_message TEXT NULL,
  execution_log MEDIUMTEXT NOT NULL,
  started_at DATETIME(3) NULL,
  completed_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  trigger_event_id BIGINT NULL,
  rule_version INT NULL,
  attempts INT NOT NULL DEFAULT 0,
  summary VARCHAR(500) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_automation_execution_event (rule_id, trigger_event_id),
  KEY idx_automation_exec_entity (tenant_id, trigger_entity_id, created_at),
  KEY idx_automation_exec_rule (rule_id, created_at),
  KEY idx_automation_exec_tenant (tenant_id, created_at),
  KEY idx_automation_exec_status (status),
  CONSTRAINT automation_executions_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT automation_executions_rule_id_fkey FOREIGN KEY (rule_id) REFERENCES automation_rules (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS integrations (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  provider VARCHAR(60) NOT NULL,
  display_name VARCHAR(200) NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  credentials_enc TEXT NULL,
  webhook_url VARCHAR(2000) NULL,
  webhook_secret_enc TEXT NULL,
  oauth_access_token_enc TEXT NULL,
  oauth_refresh_token_enc TEXT NULL,
  oauth_expires_at DATETIME(3) NULL,
  oauth_scope VARCHAR(500) NULL,
  config MEDIUMTEXT NOT NULL,
  last_synced_at DATETIME(3) NULL,
  last_error TEXT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_integration_tenant_provider (tenant_id, provider),
  UNIQUE KEY uq_integration_tenant_composite (id, tenant_id),
  CONSTRAINT integrations_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS integration_webhook_endpoints (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  integration_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  endpoint_path VARCHAR(255) NOT NULL,
  secret_hash VARCHAR(255) NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY integration_webhook_endpoints_endpoint_path_key (endpoint_path),
  KEY idx_iwe_tenant (tenant_id),
  CONSTRAINT integration_webhook_endpoints_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT integration_webhook_endpoints_integration_id_fkey FOREIGN KEY (integration_id) REFERENCES integrations (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inbound_endpoints (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  provider ENUM('meta','google','website','generic') NOT NULL,
  name VARCHAR(120) NOT NULL,
  status ENUM('active','paused') NOT NULL DEFAULT 'active',
  secret_enc TEXT NULL,
  secret_hint VARCHAR(40) NULL,
  verify_token VARCHAR(200) NULL,
  access_token_enc TEXT NULL,
  config MEDIUMTEXT NOT NULL,
  last_received_at DATETIME(3) NULL,
  received_count BIGINT NOT NULL DEFAULT 0,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY idx_inbound_endpoints_tenant (tenant_id, deleted_at, created_at),
  CONSTRAINT inbound_endpoints_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT inbound_endpoints_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inbound_events (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  endpoint_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  provider VARCHAR(20) NOT NULL,
  provider_event_id VARCHAR(200) NOT NULL,
  status ENUM('received','created','duplicate','needs_review','ignored','failed') NOT NULL DEFAULT 'received',
  is_test TINYINT(1) NOT NULL DEFAULT 0,
  payload MEDIUMTEXT NOT NULL,
  lead_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  attempts INT NOT NULL DEFAULT 0,
  reason VARCHAR(500) NULL,
  received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  processed_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_inbound_event (endpoint_id, provider_event_id),
  KEY idx_inbound_events_list (tenant_id, received_at, id),
  KEY idx_inbound_events_status (tenant_id, status, received_at),
  CONSTRAINT inbound_events_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT inbound_events_endpoint_id_fkey FOREIGN KEY (endpoint_id) REFERENCES inbound_endpoints (id) ON DELETE CASCADE,
  CONSTRAINT inbound_events_lead_id_fkey FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS outbound_endpoints (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(100) NOT NULL,
  url VARCHAR(2000) NOT NULL,
  secret_enc TEXT NOT NULL,
  secret_hint VARCHAR(40) NULL,
  events MEDIUMTEXT NOT NULL,
  status ENUM('active','paused','disabled') NOT NULL DEFAULT 'active',
  disabled_reason VARCHAR(500) NULL,
  consecutive_failures INT NOT NULL DEFAULT 0,
  last_delivery_at DATETIME(3) NULL,
  last_status INT NULL,
  last_error VARCHAR(500) NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_outbound_endpoint_tenant (id, tenant_id),
  KEY idx_outbound_endpoints_tenant (tenant_id, deleted_at, created_at),
  CONSTRAINT outbound_endpoints_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT outbound_endpoints_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS outbound_deliveries (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  endpoint_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  event_id BIGINT NULL,
  event_type VARCHAR(80) NOT NULL,
  is_test TINYINT(1) NOT NULL DEFAULT 0,
  status ENUM('pending','delivered','failed','dead','skipped') NOT NULL DEFAULT 'pending',
  attempts INT NOT NULL DEFAULT 0,
  response_status INT NULL,
  response_ms INT NULL,
  error VARCHAR(500) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  delivered_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_outbound_delivery_event (endpoint_id, event_id),
  KEY idx_outbound_deliveries_list (tenant_id, created_at, id),
  CONSTRAINT outbound_deliveries_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT fk_outbound_delivery_endpoint FOREIGN KEY (endpoint_id, tenant_id) REFERENCES outbound_endpoints (id, tenant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS messaging_accounts (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  channel ENUM('whatsapp') NOT NULL,
  display_phone VARCHAR(40) NULL,
  phone_number_id VARCHAR(40) NOT NULL,
  token_enc TEXT NOT NULL,
  token_hint VARCHAR(40) NULL,
  status ENUM('active','paused') NOT NULL DEFAULT 'active',
  last_error VARCHAR(500) NULL,
  last_sent_at DATETIME(3) NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_messaging_account (tenant_id, channel),
  CONSTRAINT messaging_accounts_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT messaging_accounts_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS api_keys (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(100) NOT NULL,
  prefix CHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  secret_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  role ENUM('tenant_owner','tenant_admin','sales_manager','sales_agent','marketing_manager','marketing_analyst','executive_readonly','auditor') NOT NULL DEFAULT 'sales_agent',
  scopes MEDIUMTEXT NOT NULL,
  created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  expires_at DATETIME(3) NULL,
  last_used_at DATETIME(3) NULL,
  last_used_ip VARCHAR(64) NULL,
  revoked_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY api_keys_prefix_key (prefix),
  KEY idx_api_keys_tenant (tenant_id, created_at),
  CONSTRAINT api_keys_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT api_keys_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── platform: audit, events, jobs, logs ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS audit_logs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  action VARCHAR(100) NOT NULL,
  entity_type VARCHAR(60) NOT NULL,
  entity_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  before_state MEDIUMTEXT NULL,
  after_state MEDIUMTEXT NULL,
  ip_address VARCHAR(64) NULL,
  correlation_id VARCHAR(64) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_audit_tenant_entity (tenant_id, entity_type, entity_id),
  KEY idx_audit_tenant_time (tenant_id, created_at, id),
  KEY idx_audit_tenant_action (tenant_id, action, created_at),
  KEY idx_audit_tenant_actor (tenant_id, actor_id, created_at),
  CONSTRAINT audit_logs_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE,
  CONSTRAINT audit_logs_actor_id_fkey FOREIGN KEY (actor_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS domain_events (
  id BIGINT NOT NULL AUTO_INCREMENT,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  type VARCHAR(80) CHARACTER SET ascii NOT NULL,
  aggregate_type VARCHAR(60) CHARACTER SET ascii NOT NULL,
  aggregate_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  actor_user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  correlation_id VARCHAR(64) NULL,
  payload MEDIUMTEXT NOT NULL,
  occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_domain_events_tenant (tenant_id, id),
  KEY idx_domain_events_aggregate (tenant_id, aggregate_type, aggregate_id, id),
  KEY idx_domain_events_occurred (occurred_at),
  CONSTRAINT domain_events_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS event_consumers (
  name VARCHAR(80) CHARACTER SET ascii NOT NULL,
  last_event_id BIGINT NOT NULL DEFAULT 0,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS jobs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  type VARCHAR(80) CHARACTER SET ascii NOT NULL,
  payload MEDIUMTEXT NOT NULL,
  status ENUM('queued','running','done','dead') NOT NULL DEFAULT 'queued',
  priority SMALLINT NOT NULL DEFAULT 0,
  run_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  attempts INT NOT NULL DEFAULT 0,
  max_attempts INT NOT NULL DEFAULT 8,
  lease_until DATETIME(3) NULL,
  locked_by VARCHAR(80) CHARACTER SET ascii NULL,
  dedupe_key VARCHAR(200) NULL,
  last_error TEXT NULL,
  result MEDIUMTEXT NULL,
  correlation_id VARCHAR(64) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  finished_at DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_jobs_dedupe (type, dedupe_key),
  KEY idx_jobs_claim (status, priority, run_at),
  KEY idx_jobs_reaper (status, lease_until),
  KEY idx_jobs_tenant (tenant_id, created_at),
  CONSTRAINT jobs_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS outbox_events (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  event_type VARCHAR(100) NOT NULL,
  payload MEDIUMTEXT NOT NULL,
  provider VARCHAR(60) NOT NULL,
  status ENUM('pending','processing','completed','failed','dead_letter') NOT NULL DEFAULT 'pending',
  attempts INT NOT NULL DEFAULT 0,
  max_attempts INT NOT NULL DEFAULT 5,
  next_retry_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_error TEXT NULL,
  response_status INT NULL,
  response_body TEXT NULL,
  idempotency_key VARCHAR(200) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY outbox_events_idempotency_key_key (idempotency_key),
  KEY idx_outbox_status_retry (status, next_retry_at),
  KEY idx_outbox_tenant (tenant_id),
  CONSTRAINT outbox_events_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS webhook_inbox (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  provider VARCHAR(60) NOT NULL,
  event_type VARCHAR(100) NOT NULL,
  provider_event_id VARCHAR(200) NOT NULL,
  payload MEDIUMTEXT NOT NULL,
  status ENUM('pending','processing','completed','failed','dead_letter') NOT NULL DEFAULT 'pending',
  attempts INT NOT NULL DEFAULT 0,
  last_error TEXT NULL,
  processed_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_webhook_provider_event (provider, provider_event_id),
  KEY idx_webhook_inbox_status (status, attempts),
  KEY idx_webhook_inbox_tenant_status (tenant_id, status, created_at),
  CONSTRAINT webhook_inbox_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS idempotency_keys (
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `key` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  request_hash CHAR(64) CHARACTER SET ascii NOT NULL,
  status_code INT NULL,
  response_body MEDIUMTEXT NULL,
  locked_until DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (tenant_id, `key`),
  KEY idx_idempotency_created (created_at),
  CONSTRAINT idempotency_keys_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS operational_logs (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  component VARCHAR(40) NOT NULL,
  severity ENUM('debug','info','warn','error','fatal') NOT NULL,
  message VARCHAR(600) NOT NULL,
  context MEDIUMTEXT NOT NULL,
  correlation_id VARCHAR(64) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (id),
  KEY idx_oplogs_tenant_time (tenant_id, created_at, id),
  KEY idx_operational_logs_created (created_at),
  CONSTRAINT operational_logs_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS system_health (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  component VARCHAR(80) NOT NULL,
  status ENUM('healthy','degraded','unhealthy') NOT NULL,
  latency_ms INT NULL DEFAULT 0,
  last_checked_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  details MEDIUMTEXT NOT NULL,
  tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  tenant_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000')) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_system_health_component_tenant (component, tenant_key),
  CONSTRAINT system_health_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS rate_buckets (
  `key` VARCHAR(200) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tokens DOUBLE NOT NULL,
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`key`),
  KEY idx_rate_buckets_updated (updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(255) NOT NULL,
  filename VARCHAR(255) NOT NULL,
  checksum VARCHAR(64) NOT NULL,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  execution_time_ms INT NOT NULL DEFAULT 0,
  PRIMARY KEY (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
